package org.kylepitcock.legacyconnector.loader.synth;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.kylepitcock.legacyconnector.loader.LegacyVersion;

/**
 * The methods vanilla declares per class (table generated by tools/extract_legacy_methods.py). Synthesized stand-ins
 * for vanilla classes get all of them, not only the ones mods call directly, so reflection over a vanilla class
 * (integrity checks like "was this method deleted from vanilla?") sees what vanilla had.
 */
public final class LegacyMethods {
    /** One declared method: name, descriptor, static. */
    public record Method(String name, String desc, boolean isStatic) {}

    private static final Map<LegacyVersion, Map<String, List<Method>>> CACHE = new HashMap<>();

    private LegacyMethods() {}

    private static synchronized Map<String, List<Method>> load(LegacyVersion version) {
        Map<String, List<Method>> map = CACHE.get(version);
        if (map != null) return map;
        map = new HashMap<>();
        String resource = "legacyconnector/legacy/" + version.id() + "/methods.txt";
        try (InputStream in = LegacyMethods.class.getClassLoader().getResourceAsStream(resource)) {
            if (in != null) {
                BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
                for (String line; (line = r.readLine()) != null; ) {
                    String[] p = line.split(" ");
                    if (p.length != 4) continue;
                    int flags = Integer.parseInt(p[3]);
                    map.computeIfAbsent(p[0], k -> new ArrayList<>()).add(new Method(p[1], p[2], (flags & 0x8) != 0));
                }
            }
        } catch (Exception e) {
            // no table: only demanded members are generated
        }
        CACHE.put(version, map);
        return map;
    }

    /** Methods of the vanilla class {@code legacyInternalName}, empty when it is not a vanilla class. */
    public static List<Method> of(LegacyVersion version, String legacyInternalName) {
        return load(version).getOrDefault(legacyInternalName, List.of());
    }
}
